const target = "e:1:can";
const on = "e:1:basket";

const pred = await tools.ego_predict({ skill: "libero_pick_place", target, on });
console.log("PRED:", JSON.stringify({ feasible: pred.feasible, withinRiskLimit: pred.withinRiskLimit, risk: pred.risk, issues: pred.issues, receipt: pred.receipt, plan: pred.plan }));

if (pred.feasible !== true || pred.withinRiskLimit !== true) {
  console.log("RESULT: " + JSON.stringify({ ok: false, stage: "predict", feasible: pred.feasible, withinRiskLimit: pred.withinRiskLimit, issues: pred.issues }));
} else {
  const run = await tools.skill_run({ receipt: pred.receipt, wait: true, timeoutS: 300 });
  const jobId = run.job ?? run.jobId ?? run.id;
  console.log("RUN:", JSON.stringify(run).slice(0, 1200));
  if (!jobId) {
    console.log("RESULT: " + JSON.stringify({ ok: false, stage: "skill_run_no_job", run }));
  } else {
    let last = run;
    let polls = 0;
    const deadline = Date.now() + 420000;
    while (last.state === "running" || last.state === "queued") {
      if (polls >= 40 || Date.now() > deadline) break;
      await new Promise((r) => setTimeout(r, 5000));
      last = await tools.skill_status({ job: jobId });
      polls += 1;
    }
    const ok = last.state === "succeeded" && last.goalStatus === "achieved" && last.stopStatus === "confirmed";
    console.log("RESULT: " + JSON.stringify({ ok, job: jobId, state: last.state, goalStatus: last.goalStatus, stopStatus: last.stopStatus, message: last.message, reasonCode: last.reasonCode, evidence: last.evidence, polls }));
  }
}

